metadata.er-schema:
{
  "title": "looply · 收藏与浏览历史 实体关系图",
  "version": "v1.5 · 2026-07-27",
  "tables": [
    {
      "name": "anonymous_identity",
      "comment": "匿名身份生命周期",
      "columns": [
        {
          "name": "anonymous_id",
          "comment": "匿名身份ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "platform",
          "comment": "载体(web/ios/android)",
          "constraint": ""
        },
        {
          "name": "issued_at",
          "comment": "首次签发时间",
          "constraint": ""
        },
        {
          "name": "expires_at",
          "comment": "固定到期时间(issued_at+12个月)",
          "constraint": ""
        },
        {
          "name": "last_seen_at",
          "comment": "最近有效请求时间(仅观察,不续期)",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态(active/expired/revoked)",
          "constraint": ""
        },
        {
          "name": "revoked_at",
          "comment": "全局隐私删除/后台撤销时间(可空)",
          "constraint": ""
        }
      ],
      "note": "设备/浏览器级假名标识 · Web/APP首次生成后固定12个月 · 所有访问和操作不续期 · 不做设备指纹或跨卸载恢复"
    },
    {
      "name": "favorite",
      "comment": "收藏",
      "columns": [
        {
          "name": "favorite_id",
          "comment": "收藏ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "user_id",
          "comment": "账户ID(用户行,可空)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "anonymous_id",
          "comment": "设备/浏览器假名ID(匿名行,可空)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "market_id",
          "comment": "商业运营市场(必填,地域快照)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "country_code",
          "comment": "经营国家/地区ISO代码(必填,地域快照)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "listing_id",
          "comment": "渠道商品(收藏对象)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "price_at_save",
          "comment": "收藏时价格快照(降价基准)",
          "constraint": ""
        },
        {
          "name": "is_active",
          "comment": "是否有效(取消收藏=false软删)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "首次创建时间(不变)",
          "constraint": ""
        },
        {
          "name": "saved_at",
          "comment": "当前收藏排序时间(重收藏刷新)",
          "constraint": ""
        },
        {
          "name": "cancelled_at",
          "comment": "最近取消时间(重收藏清空)",
          "constraint": ""
        },
        {
          "name": "count_excluded",
          "comment": "匿名收藏是否排除公开计数",
          "constraint": ""
        },
        {
          "name": "count_excluded_reason",
          "comment": "排除原因(4枚举,可空)",
          "constraint": ""
        },
        {
          "name": "count_excluded_at",
          "comment": "进入计数排除时间(可空)",
          "constraint": ""
        },
        {
          "name": "merged_from_anonymous_id",
          "comment": "溯源:由哪台匿名设备复制上移而来(原生登录态创建=NULL,可空)",
          "constraint": ""
        },
        {
          "name": "merged_at",
          "comment": "溯源:复制上移时间(原生创建=NULL,可空)",
          "constraint": ""
        }
      ],
      "note": "粒度=主体+market+country+listing · XOR单主体 · 地域为发生时快照 · 登录复制不跨地域覆盖 · saved_at排序/cancelled_at取消"
    },
    {
      "name": "browsing_history",
      "comment": "浏览历史",
      "columns": [
        {
          "name": "history_id",
          "comment": "浏览记录ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "user_id",
          "comment": "账户ID(用户行,可空)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "anonymous_id",
          "comment": "设备/浏览器假名ID(匿名行,可空)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "market_id",
          "comment": "商业运营市场(必填,地域快照)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "country_code",
          "comment": "经营国家/地区ISO代码(必填,地域快照)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "listing_id",
          "comment": "渠道商品(浏览对象)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "price_at_first_view",
          "comment": "首次浏览价格快照(降价基准,再次浏览不更新)",
          "constraint": ""
        },
        {
          "name": "first_viewed_at",
          "comment": "首次浏览时间(与首次价格成对)",
          "constraint": ""
        },
        {
          "name": "viewed_at",
          "comment": "最近浏览时间(再次浏览即更新)",
          "constraint": ""
        },
        {
          "name": "merged_from_anonymous_id",
          "comment": "溯源:由哪台匿名设备复制上移而来(原生登录态创建=NULL,可空)",
          "constraint": ""
        },
        {
          "name": "merged_at",
          "comment": "溯源:复制上移时间(原生创建=NULL,可空)",
          "constraint": ""
        }
      ],
      "note": "粒度=主体+market+country+listing · XOR单主体 · 同国家站再次浏览只更viewed_at · 登录复制按同地域删除标记过滤"
    },
    {
