          "constraint": "PRIMARY KEY"
        },
        {
          "name": "user_id",
          "comment": "目标账户ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "market_id",
          "comment": "商业运营市场(必填)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "country_code",
          "comment": "经营国家/地区ISO代码(必填)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "scope",
          "comment": "范围(item/all)",
          "constraint": ""
        },
        {
          "name": "listing_id",
          "comment": "渠道商品ID(item必填/all为NULL)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "marked_at",
          "comment": "删除抑制时间",
          "constraint": ""
