      "columns": [
        {
          "name": "user_id",
          "comment": "账户ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "用户中心拥有 · 本模块只读引用主键"
    },
    {
      "name": "market",
      "comment": "Market主数据(外部)",
      "columns": [
        {
          "name": "market_id",
          "comment": "商业运营市场ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "status",
          "comment": "Market可用状态",
          "constraint": ""
        }
      ],
      "note": "Market模块拥有 · 一个Market可包含多个国家 · 本模块只读校验"
    },
    {
      "name": "country",
      "comment": "国家/地区主数据(外部)",
      "columns": [
        {
          "name": "country_code",
          "comment": "国家/地区ISO代码",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "归属商业运营市场",
          "constraint": "FOREIGN KEY"
        },
        {
