        {
          "name": "listing_id",
          "comment": "渠道商品ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "product_id",
          "comment": "实物商品(一物一码)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "price",
          "comment": "现价(降价比对用,实时读)",
          "constraint": ""
        },
        {
          "name": "listing_status",
          "comment": "渠道状态(在售/下架/售出)",
          "constraint": ""
        }
